## 2️⃣  Initialise the map

```js
// ------------------------------------------------------------------
// 1️⃣  Create the map – any style that *does not* need a sprite is fine.
//    (We use the OSM Bright demo style just for a basemap; you can
//    replace it with your own style URL.)
const map = new maplibregl.Map({
  container: 'map',
  style: 'https://demotiles.maplibre.org/styles/osm-bright-gl-style/style.json',
  center: [-122.42, 37.77],   // San Francisco (change to your area)
  zoom: 12,
  hash: true
});
```

---

## 3️⃣  Helper: load a single SVG as an `HTMLImageElement`

```js
/**
 * Load an SVG from `url` and return a Promise that resolves with the
 * rasterised Image element.
 *
 * The image must be CORS-enabled (`crossorigin="anonymous"`).  If you
 * serve the SVGs from the same origin as the page you can omit the
 * header, otherwise make sure the server sends:
 *   Access-Control-Allow-Origin: *
 *
 * @param {string} url  – absolute URL to the SVG file
 * @returns {Promise<HTMLImageElement>}
 */
function loadSvgImage(url) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = 'anonymous';          // required for cross-origin SVGs
    img.onload  = () => resolve(img);
    img.onerror = e => reject(new Error(`Failed to load SVG ${url}`));
    img.src = url;
  });
}
```

---

## 4️⃣  Load **all** SVG icons and register them with the map

```js
// ------------------------------------------------------------------
// 2️⃣  List of icon names (without the .svg extension).  Keep this in
//     sync with the filenames you have on your server.
const iconNames = [
  'cafe', 'park', 'museum', 'library', 'restaurant', 'bar',
  'hotel', 'school', 'university', 'pharmacy', 'bank', 'atm',
  'post_office', 'hospital', 'police', 'fire_station', 'parking',
  'bicycle_rental', 'taxi', 'bus_stop', 'train_station',
  'airport', 'beach', 'campground', 'waterfall', 'mountain',
  'forest', 'garden', 'theatre', 'cinema', 'stadium',
  'shopping', 'supermarket', 'convenience', 'bakery',
  'butcher', 'pharmacy', 'hairdresser', 'beauty_salon',
  'car_repair', 'fuel', 'electric_vehicle_charging', 'toilets',
  'wifi', 'information', 'recycling', 'trash', 'dog_park'
];

// ------------------------------------------------------------------
// 3️⃣  Base URL where the SVGs live (no trailing slash)
//     Example: https://mydomain.com/icons/
const ICON_BASE_URL = 'https://mydomain.com/icons';

// ------------------------------------------------------------------
// 4️⃣  Load every SVG, then add it to the map.
//     `Promise.all` lets us wait for *all* images before we add the
//     source/layer – otherwise the layer could try to draw an icon that
//     hasn't been registered yet.
map.once('load', async () => {
  try {
    // Load all SVGs in parallel
    const loadPromises = iconNames.map(name =>
      loadSvgImage(`${ICON_BASE_URL}/${name}.svg`).then(img => ({name, img}))
    );

    const loaded = await Promise.all(loadPromises);

    // Register each image with the map (skip if the style already has it)
    loaded.forEach(({name, img}) => {
      if (!map.hasImage(name)) {
        // `addImage` options – we keep the defaults (pixelRatio: 1, sdf: false)
        map.addImage(name, img);
      }
    });

    // ----------------------------------------------------------------
    // 5️⃣  Add the GeoJSON source (replace the URL with your own)
    map.addSource('venues', {
      type: 'geojson',
      data: 'https://mydomain.com/data/venues.geojson'   // <-- your file
    });

    // ----------------------------------------------------------------
    // 6️⃣  Symbol layer that uses the icons
    map.addLayer({
      id: 'venue-icons',
      type: 'symbol',
      source: 'venues',
      // The `icon-image` is taken from the feature's `category` property.
      // It must match one of the names we added above.
      layout: {
        'icon-image': ['get', 'category'],
        // Optional: make the icons a little smaller or larger
        // 'icon-size': 0.8,

        // Keep the default collision handling (hide overlapping icons)
        // If you *do* want to force every icon to be drawn, set:
        // 'icon-allow-overlap': true,

        // If you have both an icon and a text label and want the text
        // to survive when the icon collides, enable:
        // 'icon-optional': true,

        // Example of a stretchable badge (not needed for plain icons):
        // 'icon-text-fit': 'both',
        // 'icon-text-fit-padding': [2, 2, 2, 2]
      },
      paint: {
        // If you ever use SDF icons you could colour them here:
        // 'icon-color': '#ff6600',
        // 'icon-halo-color': '#ffffff',
        // 'icon-halo-width': 1
      }
    });

    console.log('✅ All icons loaded, source & layer added.');
  } catch (err) {
    console.error('❌ Error while loading icons:', err);
  }
});
```

